import{_ as e,o as t,c as r,a as i}from"./chunks/framework.fmIt2z2h.js";const o="/xi-kari-skill/handbook/images/recovery.svg",f=JSON.parse('{"title":"依靠支持恢复的功能，算不算真的恢复","description":"支持条件不抹去已恢复的功能；它限定了恢复声明的范围。","frontmatter":{"title":"依靠支持恢复的功能，算不算真的恢复","description":"支持条件不抹去已恢复的功能；它限定了恢复声明的范围。"},"headers":[],"relativePath":"concepts/recovery.md","filePath":"concepts/recovery.md"}'),l={name:"concepts/recovery.md"};function n(s,a,c,h,p,d){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="依靠支持恢复的功能-算不算真的恢复" tabindex="-1">依靠支持恢复的功能，算不算真的恢复 <a class="header-anchor" href="#依靠支持恢复的功能-算不算真的恢复" aria-label="Permalink to &quot;依靠支持恢复的功能，算不算真的恢复&quot;">​</a></h1><p>临时供电让服务重新可用，为什么既能算恢复，又不能说一切恢复如初？</p><p><strong>支持条件不抹去已恢复的功能；它限定了恢复声明的范围。</strong></p><h2 id="从具体情景看区别" tabindex="-1">从具体情景看区别 <a class="header-anchor" href="#从具体情景看区别" aria-label="Permalink to &quot;从具体情景看区别&quot;">​</a></h2><p>原文用临时供电和持续支持说明恢复的范围。一项功能在支持下重新可用，已有结果就应该保留；不能仅因支持尚在，就把它说成没有恢复。与此同时，评价要写清依赖什么支持、在什么窗口内可用、实际覆盖了哪些人，不能把部分用户的恢复自动写成全部灾前用户均已恢复。</p><p>原文对学习作出相同的区分：支持下完成任务、撤除支持后的独立迁移、后续生活结果，是三个不同目标。若原目标本来就是协作或支持下完成，无支持失败不取消已有成功；若原目标是独立迁移，就需要相应比较。修复也不要求时间倒流，它可以改变组件、接口和载体，只要按事先明确的目标判断，并另行讨论目标、权限与责任。</p><figure class="concept-figure"><img src="'+o+'" alt="支持条件与恢复范围一起保留"><figcaption>支持下恢复、独立恢复和更广泛生活结果，具有不同的成立条件。</figcaption></figure><h2 id="回到原文" tabindex="-1">回到原文 <a class="header-anchor" href="#回到原文" aria-label="Permalink to &quot;回到原文&quot;">​</a></h2><blockquote><p>临时支持下真实恢复的功能不是假的</p></blockquote><ul><li><a href="/xi-kari-skill/handbook/theory/part-06.html#section-6-10">§6.10 解体、对象转换与修复边界</a></li><li><a href="/xi-kari-skill/handbook/theory/part-06.html#section-6-3">§6.3 CM-LEARNING 反馈介导学习</a></li><li><a href="/xi-kari-skill/handbook/theory/appendix-d/d-31.html#section-d-31">附录D.31 风险、灾害、公共卫生、指挥与恢复</a></li></ul><h2 id="这处区别能说明到哪里" tabindex="-1">这处区别能说明到哪里 <a class="header-anchor" href="#这处区别能说明到哪里" aria-label="Permalink to &quot;这处区别能说明到哪里&quot;">​</a></h2><p>这是对原文恢复和学习边界的教学说明，不是具体灾后项目或临床个案的结论。功能恢复、长期生活结果、目标正当性和采用权限须分别判断。</p><h2 id="接着理解" tabindex="-1">接着理解 <a class="header-anchor" href="#接着理解" aria-label="Permalink to &quot;接着理解&quot;">​</a></h2><ul><li><a href="./responsibility.html">实际做事的人，为什么不等于全部责任人</a></li><li><a href="./history.html">留下记录，与真正学会了什么</a></li></ul>',14)])])}const _=e(l,[["render",n]]);export{f as __pageData,_ as default};
